new:
let mut dimension = self.scene_view.dimension();
let before_dimension = dimension;
ui.selectable_value(
    &mut dimension,
    crate::scene_view::SceneViewDimension::TwoD,
    "2D",
)
.on_hover_text("Orthographic XY Native 2D authoring view");
ui.selectable_value(
